-- ===== credit-notes-statement-local.sql =====
-- LOCAL PRO ONLY. Credit notes in the customer statement and in the payment overview.
-- Read-only: no table, ledger row or credit is created or changed here.
--
-- A credit note (pro_credits kind 'credit_note', NC-0001…) is not money. Its applications to
-- an invoice draft (pro_credit_applications without invoice_application_id) reduce what the
-- customer owes on that job. Supersedes pro_client_statement_page from
-- client-statement-local.sql (same signature and output, plus the credit-note lines):
--   job due       = max(agreed − paid, 0)                (unchanged ledger figure)
--   credit notes  = Σ applications of the job's credit notes that were not reverted
--   balance       = Σ max(job due − credit notes, 0)     (a note never becomes money in favour)
--   creditCents   = Σ max(paid − agreed, 0)              (overpayment only, as before)
-- Each application is an immutable line ('credit_note', balance −amount). A reversal keeps that
-- line (reversed=true) and adds its own line ('credit_note_reversal', balance +amount).
-- pro_payment_overview_credit_notes gives the overview a separate total: credit notes are never
-- added to the received money totals.
begin;
create or replace function public.pro_credit_note_lines(p_user uuid,p_client text)
returns table(id uuid,kind text,at timestamptz,work_id text,work_title text,work_cancelled boolean,client_id text,client_name text,amount_cents bigint,
 credit_id uuid,code text,title text,reason text,draft_id uuid,draft_title text,reversed boolean)
language sql stable security invoker set search_path=public,pg_temp as $$
 select a.id,'credit_note',a.created_at,a.work_id,w.service,coalesce(w.cancelled,false),c.client_id,cl.name,a.amount_cents,
  c.id,public.pro_credit_code(c.kind,c.number),c.title,c.reason,a.draft_id,d.title,r.id is not null
 from public.pro_credit_applications a
 join public.pro_credits c on c.owner_id=a.owner_id and c.id=a.credit_id
 join public.pro_work w on w.user_id=a.owner_id and w.id=a.work_id
 join public.pro_clients cl on cl.user_id=c.owner_id and cl.id=c.client_id
 left join public.pro_invoice_drafts d on d.user_id=a.owner_id and d.id=a.draft_id
 left join public.pro_credit_application_reversals r on r.owner_id=a.owner_id and r.application_id=a.id
 where a.owner_id=p_user and c.kind='credit_note' and a.invoice_application_id is null and (p_client is null or c.client_id=p_client and w."clientId"=p_client)
 union all
 select r.id,'credit_note_reversal',r.created_at,a.work_id,w.service,coalesce(w.cancelled,false),c.client_id,cl.name,a.amount_cents,
  c.id,public.pro_credit_code(c.kind,c.number),c.title,r.reason,a.draft_id,d.title,false
 from public.pro_credit_application_reversals r
 join public.pro_credit_applications a on a.owner_id=r.owner_id and a.id=r.application_id
 join public.pro_credits c on c.owner_id=a.owner_id and c.id=a.credit_id
 join public.pro_work w on w.user_id=a.owner_id and w.id=a.work_id
 join public.pro_clients cl on cl.user_id=c.owner_id and cl.id=c.client_id
 left join public.pro_invoice_drafts d on d.user_id=a.owner_id and d.id=a.draft_id
 where r.owner_id=p_user and c.kind='credit_note' and a.invoice_application_id is null and (p_client is null or c.client_id=p_client and w."clientId"=p_client) $$;

create or replace function public.pro_client_statement_page(p_user uuid,p_client text,p_after jsonb default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_client is null or length(p_client) not between 1 and 160 then raise exception 'Invalid client' using errcode='22023';end if;
 perform pro_payment_overview_validate_cursor(p_after);
 with accounts as materialized(
 select pro_work_account(p_user,w.id) a,coalesce(to_char(pro_instant(w.start) at time zone 'UTC','YYYY-MM-DD"T"HH24:MI:SS.US"Z"'),'') at from pro_work w where w.user_id=p_user and w."clientId"=p_client
 ),
 notes as materialized(select * from pro_credit_note_lines(p_user,p_client)),
 note_totals as(select work_id,sum(amount_cents)::bigint applied from notes where kind='credit_note' and not reversed group by work_id),
 jobs as(select a,greatest((a->>'balanceCents')::bigint,0) due,greatest(-(a->>'balanceCents')::bigint,0) credit,coalesce((select applied from note_totals n where n.work_id=a->>'id'),0) notes from accounts),
 ledger as(
 select e.id,e.kind,e.work_id,w.service work_title,w.cancelled work_cancelled,e.amount_cents,e.created_at at,e.label,e.position,
 case when e.kind='agreement' then (select prev.amount_cents from pro_client_entries prev where prev.user_id=e.user_id and prev.work_id=e.work_id and prev.kind='agreement' and prev.position<e.position order by prev.position desc limit 1) else null end previous_agreement,
 exists(select 1 from pro_client_entries v where v.user_id=e.user_id and v.reversal_id=e.id and v.kind='payment_void') reversed,
 e.kind='agreement' and exists(select 1 from pro_client_entries n where n.user_id=e.user_id and n.work_id=e.work_id and n.kind='agreement' and n.position>e.position) superseded,
 case when e.kind in ('payment','payment_void') then pro_invoice_payment_metadata(p_user,case when e.kind='payment' then e.id else e.reversal_id end) else null end metadata,
 case when e.kind='payment' then e.id when e.kind='payment_void' then e.reversal_id else null end payment_id
 from pro_client_entries e join pro_work w on w.user_id=e.user_id and w.id=e.work_id where e.user_id=p_user and e.client_id=p_client and w."clientId"=p_client and e.kind in ('agreement','payment','payment_void')
 ),standalone as materialized(
 select p.*,pro_invoice_payment_metadata(p_user,p.id) metadata,pro_invoice_payment_used(p_user,p.id,null) applied from pro_invoice_payments p where p.user_id=p_user and p.client_id=p_client and p.work_id is null and p.entry_id is null
 ),events as(
 select id,at,jsonb_build_object('id',id,'kind',kind,'workId',work_id,'workTitle',work_title,'workCancelled',work_cancelled,'amountCents',amount_cents,'previousAgreementCents',previous_agreement,'balanceDeltaCents',case when kind='agreement' then amount_cents-coalesce(previous_agreement,0) when kind='payment' then -amount_cents else amount_cents end,'at',at,'receivedOn',case when kind='payment' then metadata->'receivedOn' else null end,'method',metadata->'method','reference',metadata->'reference','label',label,'reversed',reversed,'superseded',superseded,'paymentId',payment_id) document from ledger
 union all
 select id,created_at,jsonb_build_object('id',id,'kind','direct_payment','workId',null,'workTitle',null,'workCancelled',false,'amountCents',amount_cents,'previousAgreementCents',null,'balanceDeltaCents',0,'at',created_at,'receivedOn',metadata->'receivedOn','method',metadata->'method','reference',metadata->'reference','label',coalesce(metadata->>'reference',''),'reversed',false,'superseded',false,'paymentId',id) from standalone
 union all
 select id,at,jsonb_build_object('id',id,'kind',kind,'workId',work_id,'workTitle',work_title,'workCancelled',work_cancelled,'amountCents',amount_cents,'previousAgreementCents',null,'balanceDeltaCents',case when kind='credit_note' then -amount_cents else amount_cents end,'at',at,'receivedOn',null,'method',null,'reference',null,'label',title,'reversed',reversed,'superseded',false,'paymentId',null,
  'creditNote',jsonb_build_object('creditId',credit_id,'code',code,'reason',reason,'draftId',draft_id,'draftTitle',draft_title)) from notes
 ),matches as(select * from events where p_after is null or (at,id)<((p_after->>'at')::timestamptz,(p_after->>'id')::uuid) order by at desc,id desc limit 21),page as(select * from matches order by at desc,id desc limit 20)
 select jsonb_build_object('revision',md5(coalesce((select jsonb_build_object('id',id,'name',name,'archived',archived)::text from pro_clients where user_id=p_user and id=p_client),'')||coalesce((select jsonb_agg(a order by a->>'id')::text from accounts),'[]')||coalesce((select jsonb_agg(document order by at desc,id desc)::text from events),'[]')||coalesce((select jsonb_agg(jsonb_build_object('id',id,'applied',applied) order by id)::text from standalone),'[]')),'client',(select jsonb_build_object('id',id,'name',name,'archived',archived) from pro_clients where user_id=p_user and id=p_client),
 'summary',jsonb_build_object('agreedCents',coalesce((select sum((a->>'agreedCents')::bigint) from accounts),0),'paidCents',coalesce((select sum((a->>'paidCents')::bigint) from accounts),0),
  'balanceCents',coalesce((select sum(greatest(due-notes,0)) from jobs),0),'creditCents',coalesce((select sum(credit) from jobs),0),
  'creditNotesCents',coalesce((select sum(applied) from note_totals),0),'creditNoteCount',(select count(*) from notes where kind='credit_note' and not reversed),
  'unpriced',(select count(*) from accounts where a->>'agreedCents' is null and not(a->>'cancelled')::boolean),'workCount',(select count(*) from accounts),'standaloneReceivedCents',coalesce((select sum(amount_cents) from standalone),0),'standaloneAvailableCents',coalesce((select sum(amount_cents-applied) from standalone),0)),
 'items',coalesce((select jsonb_agg(document order by at desc,id desc) from page),'[]'),'nextCursor',case when (select count(*) from matches)>20 then (select jsonb_build_object('at',at,'id',id) from page order by at asc,id asc limit 1) else null end) into result
 where exists(select 1 from pro_clients where user_id=p_user and id=p_client);
 return result;
end $$;

-- Overview total of applied credit notes, filtered like the payment list where it applies:
-- customer, literal search (customer, job, code, title) and the application day in Costa Rica.
create or replace function public.pro_payment_overview_credit_notes(p_user uuid,p_query text default '',p_client text default '',p_from date default null,p_through date default null) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare result jsonb;
begin
 if p_query is null or length(p_query)>160 then raise exception 'Invalid payment query' using errcode='22023';end if;
 if p_client is null or length(p_client)>160 then raise exception 'Invalid payment client' using errcode='22023';end if;
 if p_from is not null and not isfinite(p_from) or p_through is not null and not isfinite(p_through) or p_from is not null and p_through is not null and p_from>p_through then raise exception 'Invalid payment date range' using errcode='22023';end if;
 with lines as(
  select * from pro_credit_note_lines(p_user,nullif(p_client,'')) l where l.kind='credit_note' and not l.reversed
   and strpos(pro_catalog_search(concat_ws(' ',l.client_name,l.work_title,l.code,l.title)),pro_catalog_search(p_query))>0
   and (p_from is null or (l.at at time zone 'America/Costa_Rica')::date>=p_from) and (p_through is null or (l.at at time zone 'America/Costa_Rica')::date<=p_through)
 ) select jsonb_build_object('creditNotesCents',coalesce(sum(amount_cents),0),'creditNoteCount',count(*)) into result from lines;
 return result;
end $$;
revoke all on function pro_credit_note_lines(uuid,text),pro_client_statement_page(uuid,text,jsonb),pro_payment_overview_credit_notes(uuid,text,text,date,date) from public,anon,authenticated;
grant execute on function pro_credit_note_lines(uuid,text),pro_client_statement_page(uuid,text,jsonb),pro_payment_overview_credit_notes(uuid,text,text,date,date) to service_role;
notify pgrst,'reload schema';
commit;

-- ===== bid-vendor-portal-local.sql =====
-- LOCAL PRO ONLY. Vendor portal for bid packages (parity register row 53, "portal de proveedores").
-- The owner creates an invitation link for ONE invited vendor of ONE bid package and copies it
-- (nothing is e-mailed or sent). The link carries a random token (randomBytes(32), never derived
-- from stored data); only its keyed hash (HMAC-SHA256 with PRO_BID_PORTAL_SECRET, hex) is stored.
-- Retrying the same create action returns the link without the token (it cannot be shown again).
--  * Single use: the first visit claims the link and opens a vendor session (its own random
--    token, also stored only as a keyed hash, kept by the vendor's browser in an httpOnly cookie
--    named after the link). A second visit with the same link is refused, except from the same
--    browser (device hash) within 2 minutes of the claim, which rotates the session (lost reply).
--  * Expiry (1-30 days) and revocation. A new link for the same vendor revokes the previous one.
--  * The vendor sees only its invitation: package code, title, scope, due date and lines
--    (description, quantity, unit), and only the offer IT sent from the portal (last row of
--    pro_bid_portal_submissions), never the owner's notes or an offer typed by the owner.
--    Never budget items, internal costs, other vendors, their offers, the comparison or awards.
--  * Submitting or updating the offer is allowed while the package is open and not past its
--    due date (Costa Rica day). It goes through pro_bids_mutate('record_response'), so the
--    owner's comparison, validation, package revision and history are the same as an offer
--    typed by the owner, under an internal action id derived from the link and the vendor's id.
--    Vendor receipts are idempotent per link and action id; the vendor view revision (CAS)
--    prevents overwriting a newer offer from another tab (40001). At most 50 offers per link
--    (SQLSTATE CR429 -> 429).
--  * A vendor with portal offers cannot be removed from the package (uninvite): the immutable
--    record would be lost (hint pro_bid_portal_submissions).
-- Lock order (submit and uninvite): bid work advisory 'pro-bid-work:<owner>:<work>' first, then
-- the link rows. Owner link writers and claim only lock link rows. Reapplicable.
begin;
create table if not exists public.pro_bid_portal_links(
 owner_id uuid not null references public.profiles(id) on delete cascade,id uuid not null,
 package_id uuid not null,supplier_id uuid not null,
 token_hash bytea not null check(length(token_hash)=32),
 expires_at timestamptz not null,created_at timestamptz not null default now(),
 claimed_at timestamptz,session_hash bytea check(session_hash is null or length(session_hash)=32),
 revoked_at timestamptz,revoke_reason text check(revoke_reason is null or revoke_reason in('owner','replaced')),
 revision integer not null default 1 check(revision>0),
 primary key(owner_id,id),
 foreign key(owner_id,package_id,supplier_id) references public.pro_bid_invitations(owner_id,package_id,supplier_id) on delete cascade deferrable initially deferred,
 check((claimed_at is null)=(session_hash is null)),
 check((revoked_at is null)=(revoke_reason is null)),
 check(expires_at>created_at and expires_at<=created_at+interval '30 days 1 minute')
);
-- Keyed hash of the claiming browser's device id: allows a short re-claim window (lost reply).
alter table public.pro_bid_portal_links add column if not exists claim_device_hash bytea check(claim_device_hash is null or length(claim_device_hash)=32);
create unique index if not exists pro_bid_portal_link_id on public.pro_bid_portal_links(id);
create unique index if not exists pro_bid_portal_token on public.pro_bid_portal_links(token_hash);
create unique index if not exists pro_bid_portal_session on public.pro_bid_portal_links(session_hash) where session_hash is not null;
create unique index if not exists pro_bid_portal_one_active on public.pro_bid_portal_links(owner_id,package_id,supplier_id) where revoked_at is null;
-- Immutable record of every offer the vendor sent from the portal.
create table if not exists public.pro_bid_portal_submissions(
 owner_id uuid not null references public.profiles(id) on delete cascade,link_id uuid not null,action_id uuid not null,
 package_id uuid not null,supplier_id uuid not null,input jsonb not null,result jsonb not null,submitted_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,link_id,action_id),
 foreign key(owner_id,link_id) references public.pro_bid_portal_links(owner_id,id) on delete cascade
);
create index if not exists pro_bid_portal_submissions_vendor on public.pro_bid_portal_submissions(owner_id,package_id,supplier_id,submitted_at desc);
-- Owner receipts for link actions (create/revoke), idempotent per actor and action id.
create table if not exists public.pro_bid_portal_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);

create or replace function public.pro_bid_portal_hash(p_value text) returns bytea
language plpgsql immutable security invoker set search_path=public,pg_temp as $$
begin
 if p_value is null or p_value !~ '^[0-9a-f]{64}$' then raise exception 'Invalid token hash' using errcode='22023';end if;
 return decode(p_value,'hex');
end $$;
-- Internal action id for pro_bids_mutate, derived from the link and the vendor's action id.
-- md5 alone is not an RFC 9562 UUID (version/variant bits are random) and the owner's API
-- schemas (z.uuid(): history, receipts) reject it, so set version 8 (custom) and variant 10.
create or replace function public.pro_bid_portal_action_id(p_link uuid,p_action uuid) returns uuid
language sql immutable security invoker set search_path=public,pg_temp as $$
 select overlay(overlay(h placing '8' from 13 for 1) placing substr('89ab',(('x'||substr(h,17,1))::bit(4)::integer&3)+1,1) from 17 for 1)::uuid
 from (select md5('bid-portal:'||p_link::text||':'||p_action::text) h) d $$;
create or replace function public.pro_bid_portal_status(p_row public.pro_bid_portal_links) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_row.revoked_at is not null then 'revoked' when p_row.expires_at<=now() then 'expired' when p_row.claimed_at is not null then 'claimed' else 'active' end $$;
create or replace function public.pro_bid_portal_link_json(p_row public.pro_bid_portal_links) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'packageId',p_row.package_id,'supplierId',p_row.supplier_id,'status',public.pro_bid_portal_status(p_row),
  'createdAt',p_row.created_at,'expiresAt',p_row.expires_at,'claimedAt',p_row.claimed_at,'revokedAt',p_row.revoked_at,'revokeReason',p_row.revoke_reason,'revision',p_row.revision,
  'submissionCount',(select count(*)::integer from public.pro_bid_portal_submissions s where s.owner_id=p_row.owner_id and s.link_id=p_row.id),
  'lastSubmittedAt',(select max(s.submitted_at) from public.pro_bid_portal_submissions s where s.owner_id=p_row.owner_id and s.link_id=p_row.id)) $$;

-- Owner: current link and last portal offer for every invited vendor of one package.
create or replace function public.pro_bid_portal_owner_read(p_actor uuid,p_query jsonb) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare keys text[];pid uuid;r public.pro_bid_packages;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_query) is distinct from 'object' then raise exception 'Invalid query' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_query) key;
 if keys is distinct from array['id','workId'] or jsonb_typeof(p_query->'workId') is distinct from 'string' or length(p_query->>'workId') not between 1 and 160 then raise exception 'Invalid query' using errcode='22023';end if;
 pid:=public.pro_bid_uuid_value(p_query->'id');
 select * into r from public.pro_bid_packages where owner_id=p_actor and work_id=p_query->>'workId' and id=pid;
 if not found then return null;end if;
 return jsonb_build_object('packageId',r.id,'status',r.status,'dueDate',r.due_date,'today',public.pro_bid_today(),
  'vendors',coalesce((select jsonb_agg(jsonb_build_object('supplierId',i.supplier_id,
    'link',(select public.pro_bid_portal_link_json(l) from public.pro_bid_portal_links l where l.owner_id=i.owner_id and l.package_id=i.package_id and l.supplier_id=i.supplier_id order by l.created_at desc,l.id limit 1),
    'portalSubmissions',(select count(*)::integer from public.pro_bid_portal_submissions s where s.owner_id=i.owner_id and s.package_id=i.package_id and s.supplier_id=i.supplier_id),
    'lastPortalSubmissionAt',(select max(s.submitted_at) from public.pro_bid_portal_submissions s where s.owner_id=i.owner_id and s.package_id=i.package_id and s.supplier_id=i.supplier_id))
   order by i.supplier_id) from public.pro_bid_invitations i where i.owner_id=p_actor and i.package_id=pid),'[]'::jsonb));
end $$;

-- Owner: create (replacing the active link) or revoke a link. The route generates the token
-- and passes only its SHA-256 (hex). CAS: create names the link it replaces (or null), revoke
-- names the link and its revision.
create or replace function public.pro_bid_portal_owner_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;pid uuid;sid uuid;lid uuid;wid text;receipt public.pro_bid_portal_actions;r public.pro_bid_packages;cur public.pro_bid_portal_links;l public.pro_bid_portal_links;
 days integer;hash bytea;result jsonb;replaces uuid;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid link' using errcode='22023';end if;
 act:=p_input->>'action';
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from (case act when 'create_link' then array['action','actionId','expiresInDays','id','packageId','replacesLinkId','supplierId','tokenHash','workId']
   when 'revoke_link' then array['action','actionId','id','packageId','revision','supplierId','workId'] end)
  or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid link fields' using errcode='22023';end if;
 wid:=p_input->>'workId';aid:=public.pro_bid_uuid_value(p_input->'actionId');lid:=public.pro_bid_uuid_value(p_input->'id');pid:=public.pro_bid_uuid_value(p_input->'packageId');sid:=public.pro_bid_uuid_value(p_input->'supplierId');
 if act='create_link' then
  hash:=public.pro_bid_portal_hash(p_input->>'tokenHash');
  if jsonb_typeof(p_input->'expiresInDays') is distinct from 'number' or not coalesce((p_input->>'expiresInDays')~'^[0-9]{1,2}$',false) or (p_input->>'expiresInDays')::integer not between 1 and 30 then raise exception 'Invalid expiry' using errcode='22023';end if;
  days:=(p_input->>'expiresInDays')::integer;
  if jsonb_typeof(p_input->'replacesLinkId')='null' then replaces:=null;else replaces:=public.pro_bid_uuid_value(p_input->'replacesLinkId');end if;
 elsif jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid revision' using errcode='22023';
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-bid-portal-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_bid_portal_actions where actor_id=p_actor and action_id=aid;
 if found then
  -- The token is random per request: a retried create (same action, same fields) replays the
  -- receipt without any token; the owner replaces the link to get a new one.
  if (case when act='create_link' then receipt.input-'tokenHash' else receipt.input end) is distinct from (case when act='create_link' then p_input-'tokenHash' else p_input end) then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result||jsonb_build_object('replayed',true);
 end if;
 select * into r from public.pro_bid_packages where owner_id=p_actor and work_id=wid and id=pid;
 if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_bid_invitations where owner_id=p_actor and package_id=pid and supplier_id=sid) then raise exception 'Vendor not invited' using errcode='22023';end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-bid-portal-vendor:'||p_actor::text||':'||pid::text||':'||sid::text,0));
 select * into cur from public.pro_bid_portal_links where owner_id=p_actor and package_id=pid and supplier_id=sid and revoked_at is null for update;
 if act='create_link' then
  if r.status not in('draft','open') then raise exception 'Links are created before the bid closes' using errcode='22023';end if;
  if (cur.id is null)<>(replaces is null) or cur.id is distinct from replaces then raise exception 'Link changed' using errcode='40001';end if;
  if exists(select 1 from public.pro_bid_portal_links where id=lid) then raise exception 'Link id already used' using errcode='23505';end if;
  if (select count(*) from public.pro_bid_portal_links where owner_id=p_actor and package_id=pid)>=200 then raise exception 'Link limit' using errcode='54000';end if;
  if cur.id is not null then update public.pro_bid_portal_links set revoked_at=now(),revoke_reason='replaced',revision=revision+1 where owner_id=p_actor and id=cur.id;end if;
  insert into public.pro_bid_portal_links(owner_id,id,package_id,supplier_id,token_hash,expires_at) values(p_actor,lid,pid,sid,hash,now()+make_interval(days=>days)) returning * into l;
 else
  if cur.id is distinct from lid then raise exception 'Link changed' using errcode='40001';end if;
  if cur.revision<>(p_input->>'revision')::integer then raise exception 'Link changed' using errcode='40001';end if;
  update public.pro_bid_portal_links set revoked_at=now(),revoke_reason='owner',revision=revision+1 where owner_id=p_actor and id=lid returning * into l;
 end if;
 result:=jsonb_build_object('link',public.pro_bid_portal_link_json(l));
 insert into public.pro_bid_portal_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Vendor: claim a link once. Returns ok=false (no detail beyond the reason) for unknown, used,
-- revoked or expired links. 'link' is returned for 'used' only so the route can reopen this
-- browser's own session cookie; the route drops it otherwise. The same device may claim again
-- within 2 minutes (its reply was lost): the session is rotated, never shared.
drop function if exists public.pro_bid_portal_claim(text,text);
create or replace function public.pro_bid_portal_claim(p_token_hash text,p_session_hash text,p_device_hash text default null) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare token bytea:=public.pro_bid_portal_hash(p_token_hash);session bytea:=public.pro_bid_portal_hash(p_session_hash);
 device bytea:=case when p_device_hash is null then null else public.pro_bid_portal_hash(p_device_hash) end;l public.pro_bid_portal_links;r public.pro_bid_packages;regrant boolean:=false;
begin
 select * into l from public.pro_bid_portal_links where token_hash=token for update;
 if not found then return jsonb_build_object('ok',false,'reason','unknown');end if;
 if l.revoked_at is not null then return jsonb_build_object('ok',false,'reason','revoked');end if;
 if l.expires_at<=now() then return jsonb_build_object('ok',false,'reason','expired');end if;
 if l.claimed_at is not null then
  if device is null or l.claim_device_hash is distinct from device or l.claimed_at<=now()-interval '2 minutes' then return jsonb_build_object('ok',false,'reason','used','link',l.id);end if;
  regrant:=true;
 end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found or r.status in('cancelled','awarded') or not coalesce(public.pro_private_work_tools_enabled(l.owner_id),false) then return jsonb_build_object('ok',false,'reason','unavailable');end if;
 if regrant then update public.pro_bid_portal_links set session_hash=session,revision=revision+1 where owner_id=l.owner_id and id=l.id returning * into l;
 else update public.pro_bid_portal_links set claimed_at=now(),session_hash=session,claim_device_hash=device,revision=revision+1 where owner_id=l.owner_id and id=l.id returning * into l;end if;
 return jsonb_build_object('ok',true,'link',l.id,'expiresAt',l.expires_at,'regranted',regrant);
end $$;

-- Vendor view of its own invitation (no internal data). Null when the session is not valid.
create or replace function public.pro_bid_portal_view(p_session_hash text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare session bytea:=public.pro_bid_portal_hash(p_session_hash);l public.pro_bid_portal_links;r public.pro_bid_packages;s public.pro_expense_suppliers;sub public.pro_bid_portal_submissions;today date:=public.pro_bid_today();
begin
 select * into l from public.pro_bid_portal_links where session_hash=session;
 if not found or l.revoked_at is not null or l.expires_at<=now() or not coalesce(public.pro_private_work_tools_enabled(l.owner_id),false) then return null;end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found or not exists(select 1 from public.pro_bid_invitations i where i.owner_id=l.owner_id and i.package_id=l.package_id and i.supplier_id=l.supplier_id) then return null;end if;
 select * into s from public.pro_expense_suppliers where user_id=l.owner_id and id=l.supplier_id;
 -- Only what this vendor sent from the portal (any of its links), while the offer is on record.
 -- Never pro_bid_responses: the owner may have typed notes or an offer there by hand.
 select x.* into sub from public.pro_bid_portal_submissions x where x.owner_id=l.owner_id and x.package_id=l.package_id and x.supplier_id=l.supplier_id
  and exists(select 1 from public.pro_bid_responses resp where resp.owner_id=x.owner_id and resp.package_id=x.package_id and resp.supplier_id=x.supplier_id)
  order by x.submitted_at desc,x.action_id desc limit 1;
 return jsonb_build_object(
  'revision',l.revision,'expiresAt',l.expires_at,'today',today,
  'business',coalesce((select nullif(btrim(p.business_name),'') from public.professionals p where p.profile_id=l.owner_id limit 1),(select nullif(btrim(f.full_name),'') from public.profiles f where f.id=l.owner_id)),
  'vendor',s.name,
  'package',jsonb_build_object('code','LIC-'||lpad(r.number::text,4,'0'),'title',r.title,'scope',r.scope,'dueDate',r.due_date,
    'status',case when r.status='open' and r.due_date>=today then 'open' when r.status in('open','closed') then 'closed' else r.status end,
    'lines',coalesce((select jsonb_agg(jsonb_build_object('id',x.id,'position',x.position,'description',x.description,'quantity',x.quantity,'unit',x.unit) order by x.position)
      from public.pro_bid_lines x where x.owner_id=r.owner_id and x.package_id=r.id),'[]'::jsonb)),
  'offer',case when sub.link_id is null then null else jsonb_build_object('receivedOn',sub.result->>'submittedOn','leadDays',sub.input->'leadDays','validUntil',sub.input->'validUntil','notes',sub.input->'notes','recordedAt',sub.submitted_at,
    'prices',coalesce((select jsonb_agg(jsonb_build_object('lineId',x.id,'unitCents',(p->>'unitCents')::bigint,'totalCents',round(x.quantity*(p->>'unitCents')::bigint)::bigint) order by x.position)
      from jsonb_array_elements(sub.input->'prices') p join public.pro_bid_lines x on x.owner_id=l.owner_id and x.package_id=l.package_id and x.id=(p->>'lineId')::uuid),'[]'::jsonb)) end,
  'submissions',(select count(*)::integer from public.pro_bid_portal_submissions x where x.owner_id=l.owner_id and x.link_id=l.id));
end $$;

-- Vendor: send or update its offer while the package is open and not past its due date.
create or replace function public.pro_bid_portal_submit(p_session_hash text,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare session bytea:=public.pro_bid_portal_hash(p_session_hash);l public.pro_bid_portal_links;r public.pro_bid_packages;keys text[];aid uuid;prior public.pro_bid_portal_submissions;answer jsonb;result jsonb;today date:=public.pro_bid_today();
begin
 if jsonb_typeof(p_input) is distinct from 'object' then raise exception 'Invalid offer' using errcode='22023';end if;
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from array['actionId','leadDays','notes','prices','revision','validUntil'] then raise exception 'Invalid offer fields' using errcode='22023';end if;
 if jsonb_typeof(p_input->'revision') is distinct from 'number' or not coalesce((p_input->>'revision')~'^[0-9]{1,10}$',false) or (p_input->>'revision')::numeric not between 1 and 2147483646 then raise exception 'Invalid revision' using errcode='22023';end if;
 aid:=public.pro_bid_uuid_value(p_input->'actionId');
 select * into l from public.pro_bid_portal_links where session_hash=session;
 if not found or l.revoked_at is not null or l.expires_at<=now() or not coalesce(public.pro_private_work_tools_enabled(l.owner_id),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 -- Same lock order as pro_bids_mutate (uninvite, record_response): work advisory, then the link row.
 perform pg_advisory_xact_lock(hashtextextended('pro-bid-work:'||l.owner_id::text||':'||r.work_id,0));
 select * into l from public.pro_bid_portal_links where owner_id=l.owner_id and id=l.id for update;
 if not found or l.session_hash is distinct from session or l.revoked_at is not null or l.expires_at<=now() then raise exception 'Forbidden' using errcode='42501';end if;
 select * into prior from public.pro_bid_portal_submissions where owner_id=l.owner_id and link_id=l.id and action_id=aid;
 if found then
  if prior.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return prior.result||jsonb_build_object('replayed',true);
 end if;
 if l.revision<>(p_input->>'revision')::integer then raise exception 'Offer changed' using errcode='40001';end if;
 select * into r from public.pro_bid_packages where owner_id=l.owner_id and id=l.package_id;
 if not found or r.status<>'open' or r.due_date<today then raise exception 'The bid is closed' using errcode='22023',hint='pro_bid_portal_closed';end if;
 if (select count(*) from public.pro_bid_portal_submissions where owner_id=l.owner_id and link_id=l.id)>=50 then raise exception 'Submission limit for this link' using errcode='CR429',hint='pro_bid_portal_submission_limit';end if;
 -- Same writer, validation and history as an offer recorded by the owner. Internal action id
 -- derived from the link: the vendor's id never enters the owner's receipt space.
 answer:=public.pro_bids_mutate(l.owner_id,jsonb_build_object('action','record_response','actionId',public.pro_bid_portal_action_id(l.id,aid),'id',r.id,'workId',r.work_id,'revision',r.revision,'supplierId',l.supplier_id,
  'receivedOn',to_char(today,'YYYY-MM-DD'),'validUntil',p_input->'validUntil','leadDays',p_input->'leadDays','notes',p_input->'notes','prices',p_input->'prices'));
 if answer is null then raise exception 'Offer not recorded' using errcode='22023';end if;
 update public.pro_bid_portal_links set revision=revision+1 where owner_id=l.owner_id and id=l.id returning * into l;
 result:=jsonb_build_object('ok',true,'revision',l.revision,'submittedOn',to_char(today,'YYYY-MM-DD'));
 insert into public.pro_bid_portal_submissions(owner_id,link_id,action_id,package_id,supplier_id,input,result) values(l.owner_id,l.id,aid,l.package_id,l.supplier_id,p_input,result);
 return result;
end $$;

create or replace function public.pro_bid_portal_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Portal submissions and receipts are immutable' using errcode='23514';end $$;
drop trigger if exists pro_bid_portal_submission_immutable on public.pro_bid_portal_submissions;
create trigger pro_bid_portal_submission_immutable before update on public.pro_bid_portal_submissions for each row execute function public.pro_bid_portal_immutable();
drop trigger if exists pro_bid_portal_action_immutable on public.pro_bid_portal_actions;
create trigger pro_bid_portal_action_immutable before update on public.pro_bid_portal_actions for each row execute function public.pro_bid_portal_immutable();
-- A link never changes target, token or creation; only claim/revoke fields move forward.
create or replace function public.pro_bid_portal_link_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.owner_id<>old.owner_id or new.id<>old.id or new.package_id<>old.package_id or new.supplier_id<>old.supplier_id or new.token_hash<>old.token_hash or new.expires_at<>old.expires_at or new.created_at<>old.created_at
  or old.claimed_at is null and new.claimed_at is null and new.claim_device_hash is not null
  or old.claimed_at is not null and (new.claimed_at is distinct from old.claimed_at or new.claim_device_hash is distinct from old.claim_device_hash
   -- The session only rotates in the claiming device's 2-minute re-claim window.
   or new.session_hash is distinct from old.session_hash and (old.claim_device_hash is null or old.claimed_at<=now()-interval '2 minutes'))
  or old.revoked_at is not null and (new.revoked_at is distinct from old.revoked_at or new.revoke_reason is distinct from old.revoke_reason) then
  raise exception 'Portal links only move forward' using errcode='23514';
 end if;
 return new;
end $$;
drop trigger if exists pro_bid_portal_link_guard on public.pro_bid_portal_links;
create trigger pro_bid_portal_link_guard before update on public.pro_bid_portal_links for each row execute function public.pro_bid_portal_link_guard();
-- uninvite (a direct delete of the invitation, inside pro_bids_mutate after its work advisory):
-- lock the vendor's link rows in the shared order and keep the immutable portal record. Deletes
-- cascaded from a removed account or package (trigger depth > 1) are not blocked.
create or replace function public.pro_bid_portal_invitation_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if pg_trigger_depth()=1 then
  perform 1 from public.pro_bid_portal_links where owner_id=old.owner_id and package_id=old.package_id and supplier_id=old.supplier_id for update;
  if exists(select 1 from public.pro_bid_portal_submissions where owner_id=old.owner_id and package_id=old.package_id and supplier_id=old.supplier_id) then
   raise exception 'The vendor sent offers from the portal' using errcode='22023',hint='pro_bid_portal_submissions';
  end if;
 end if;
 return old;
end $$;
drop trigger if exists pro_bid_portal_invitation_guard on public.pro_bid_invitations;
create trigger pro_bid_portal_invitation_guard before delete on public.pro_bid_invitations for each row execute function public.pro_bid_portal_invitation_guard();

do $$declare t text;f record;begin
 foreach t in array array['pro_bid_portal_links','pro_bid_portal_submissions','pro_bid_portal_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_bid\_portal\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname not in('pro_bid_portal_immutable','pro_bid_portal_link_guard','pro_bid_portal_invitation_guard') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== company-file-versions-local.sql =====
-- LOCAL PRO ONLY. Versions in the company library (Empresa › Archivos; parity register row 30).
-- Reuses the model of file-versions-local.sql for pro_company_files, never exposed to customers:
--  * A family groups library files; its id is its first file (the root). A file without versions is an
--    implicit family of one (v1). The family row is created on the first add_version.
--  * pro_company_file_versions is append-only (v1, v2, …). add_version attaches a freshly uploaded
--    library file (same upload route, normalization and hash checks); restore appends a NEW entry that
--    points at an older entry's file. Nothing is deleted or rewritten. The family points at the current file.
--  * The library lists only the CURRENT file of each family, so open, download and «Usar en trabajo»
--    act on the current version (a copy to a job stays a private work file, as before). The file that
--    becomes current inherits the folder and favourite of the previous one; moving the current file
--    moves every member, so older versions stay downloadable from the same folder.
--  * Pattern: closed RLS + revoke, security invoker RPCs for service_role only, eligibility
--    pro_appointment_enabled (library) and pro_private_work_tools_enabled, family revision CAS
--    (40001 -> 409), idempotent receipts per actionId (other payload -> 22023), immutable versions,
--    members and receipts, Costa Rica day (dayCr). Limit: 100 versions per family (54000 -> 429).
-- Lock order: action advisory -> 'pro-company-files:<owner>' advisory (the library writer's key) -> family.
-- Supersedes pro_company_files_read from company-files-local.sql (same signature and output; it only
-- leaves out the non-current versions). Reapplicable; new objects otherwise.
begin;
create table if not exists public.pro_company_file_families(
 owner_id uuid not null references public.profiles(id) on delete cascade,root_id uuid not null,current_version integer not null check(current_version between 1 and 100),
 current_file_id uuid not null,revision integer not null default 1 check(revision>0),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),
 primary key(owner_id,root_id),
 foreign key(owner_id,root_id) references public.pro_company_files(owner_id,id) on delete cascade,
 foreign key(owner_id,current_file_id) references public.pro_company_files(owner_id,id) on delete cascade
);
create table if not exists public.pro_company_file_family_members(
 owner_id uuid not null,file_id uuid not null,root_id uuid not null,primary key(owner_id,file_id),
 foreign key(owner_id,root_id) references public.pro_company_file_families(owner_id,root_id) on delete cascade,
 foreign key(owner_id,file_id) references public.pro_company_files(owner_id,id) on delete cascade
);
create index if not exists pro_company_file_members_root on public.pro_company_file_family_members(owner_id,root_id);
create table if not exists public.pro_company_file_versions(
 owner_id uuid not null,root_id uuid not null,version integer not null check(version between 1 and 100),file_id uuid not null,
 kind text not null check(kind in('original','upload','restore')),restored_from integer check(restored_from is null or restored_from between 1 and 100),
 note text check(note is null or length(btrim(note)) between 1 and 500),created_at timestamptz not null default clock_timestamp(),
 primary key(owner_id,root_id,version),
 foreign key(owner_id,root_id) references public.pro_company_file_families(owner_id,root_id) on delete cascade,
 foreign key(owner_id,file_id) references public.pro_company_files(owner_id,id) on delete cascade,
 check((kind='restore')=(restored_from is not null) and (restored_from is null or restored_from<version))
);
create table if not exists public.pro_company_file_version_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),primary key(actor_id,action_id)
);

create or replace function public.pro_cfv_enabled(p_actor uuid) returns boolean
language sql volatile security invoker set search_path=public,pg_temp as $$
 select coalesce(public.pro_appointment_enabled(p_actor),false) and coalesce(public.pro_private_work_tools_enabled(p_actor),false) $$;
-- A member that is not the current file of its family is never listed.
create or replace function public.pro_cfv_hidden(p_owner uuid,p_file uuid) returns boolean
language sql stable security invoker set search_path=public,pg_temp as $$
 select exists(select 1 from public.pro_company_file_family_members m join public.pro_company_file_families f on f.owner_id=m.owner_id and f.root_id=m.root_id
  where m.owner_id=p_owner and m.file_id=p_file and f.current_file_id<>p_file) $$;
create or replace function public.pro_cfv_root(p_owner uuid,p_file uuid) returns uuid
language sql stable security invoker set search_path=public,pg_temp as $$
 select coalesce((select m.root_id from public.pro_company_file_family_members m where m.owner_id=p_owner and m.file_id=p_file),p_file) $$;
create or replace function public.pro_cfv_state(p_owner uuid,p_root uuid) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 with fam as(select * from public.pro_company_file_families where owner_id=p_owner and root_id=p_root),
 rows as(
  select v.version,v.kind,v.restored_from,v.note,v.created_at version_at,f.id,f.name,f.mime_type,f.size_bytes,f.sha256,f.created_at file_at from public.pro_company_file_versions v join public.pro_company_files f on f.owner_id=v.owner_id and f.id=v.file_id
   where v.owner_id=p_owner and v.root_id=p_root
  union all
  select 1,'original',null,null,f.created_at,f.id,f.name,f.mime_type,f.size_bytes,f.sha256,f.created_at from public.pro_company_files f where f.owner_id=p_owner and f.id=p_root and not exists(select 1 from fam)
 )
 select jsonb_build_object('rootId',p_root,'revision',coalesce((select revision from fam),0),
  'currentVersion',coalesce((select current_version from fam),1),'currentFileId',coalesce((select current_file_id from fam),p_root),
  'versions',coalesce((select jsonb_agg(jsonb_build_object('version',r.version,'kind',r.kind,'restoredFrom',r.restored_from,'note',r.note,'createdAt',r.version_at,
     'dayCr',to_char(r.version_at at time zone 'America/Costa_Rica','YYYY-MM-DD'),'current',r.version=coalesce((select current_version from fam),1),
     'file',jsonb_build_object('id',r.id,'name',r.name,'mimeType',r.mime_type,'sizeBytes',r.size_bytes,'sha256',r.sha256,'createdAt',r.file_at)) order by r.version desc) from rows r),'[]'::jsonb)) $$;

create or replace function public.pro_company_file_versions_read(p_actor uuid,p_file uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare root uuid;
begin
 if not public.pro_cfv_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_file is null then raise exception 'Invalid file' using errcode='22023';end if;
 if not exists(select 1 from public.pro_company_files where owner_id=p_actor and id=p_file and ready) then return null;end if;
 root:=public.pro_cfv_root(p_actor,p_file);
 return public.pro_cfv_state(p_actor,root);
end $$;
-- Badges for one page of the list (≤ 20 files).
create or replace function public.pro_company_file_versions_index(p_actor uuid,p_files uuid[]) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
begin
 if not public.pro_cfv_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_files is null or cardinality(p_files)>20 then raise exception 'Invalid files' using errcode='22023';end if;
 return coalesce((select jsonb_agg(jsonb_build_object('fileId',m.file_id,'rootId',f.root_id,'currentVersion',f.current_version,
   'versionCount',(select count(*)::integer from public.pro_company_file_versions v where v.owner_id=f.owner_id and v.root_id=f.root_id)) order by m.file_id)
  from public.pro_company_file_family_members m join public.pro_company_file_families f on f.owner_id=m.owner_id and f.root_id=m.root_id
  where m.owner_id=p_actor and m.file_id=any(p_files) and f.current_file_id=m.file_id),'[]'::jsonb);
end $$;

create or replace function public.pro_company_file_versions_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;keys text[];aid uuid;fid uuid;nid uuid;rev integer;v_note text;v_version integer;receipt public.pro_company_file_version_actions;
 root uuid;fam public.pro_company_file_families;cur public.pro_company_files;nf public.pro_company_files;target public.pro_company_file_versions;next_version integer;result jsonb;
begin
 if not public.pro_cfv_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid version' using errcode='22023';end if;
 act:=p_input->>'action';
 select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from (case act when 'add_version' then array['action','actionId','fileId','newFileId','note','revision'] when 'restore' then array['action','actionId','fileId','note','revision','version'] end) then raise exception 'Invalid version fields' using errcode='22023';end if;
 aid:=public.pro_wfv_uuid(p_input->'actionId');fid:=public.pro_wfv_uuid(p_input->'fileId');rev:=public.pro_wfv_int(p_input->'revision',0,2147483646);v_note:=public.pro_wfv_text(p_input->'note',500,false);
 if act='add_version' then nid:=public.pro_wfv_uuid(p_input->'newFileId');else v_version:=public.pro_wfv_int(p_input->'version',1,100);end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-file-version-action:'||p_actor::text||':'||aid::text,0));
 select * into receipt from public.pro_company_file_version_actions where actor_id=p_actor and action_id=aid;
 if found then
  if receipt.input is distinct from p_input then raise exception 'Action identity reused with different payload' using errcode='22023';end if;
  return receipt.result;
 end if;
 perform pg_advisory_xact_lock(hashtextextended('pro-company-files:'||p_actor::text,0));
 if not public.pro_cfv_enabled(p_actor) then raise exception 'Forbidden' using errcode='42501';end if;
 if not exists(select 1 from public.pro_company_files where owner_id=p_actor and id=fid and ready) then raise exception 'File unavailable' using errcode='42501';end if;
 root:=public.pro_cfv_root(p_actor,fid);
 select * into fam from public.pro_company_file_families where owner_id=p_actor and root_id=root for update;
 if coalesce(fam.revision,0)<>rev then raise exception 'Versions changed' using errcode='40001';end if;
 select * into cur from public.pro_company_files where owner_id=p_actor and id=coalesce(fam.current_file_id,root) for update;
 if not found or not cur.ready then raise exception 'File unavailable' using errcode='42501';end if;
 if cur.archived then raise exception 'Restore the file before changing its versions' using errcode='22023';end if;
 if act='add_version' then
  select * into nf from public.pro_company_files where owner_id=p_actor and id=nid for update;
  if not found or not nf.ready then raise exception 'Upload the new version first' using errcode='22023';end if;
  if nf.id=cur.id or nf.archived or exists(select 1 from public.pro_company_file_family_members where owner_id=p_actor and file_id=nid)
   or exists(select 1 from public.pro_company_file_families where owner_id=p_actor and root_id=nid) then raise exception 'That file cannot become a version' using errcode='22023';end if;
 end if;
 if fam.root_id is null then
  insert into public.pro_company_file_families(owner_id,root_id,current_version,current_file_id) values(p_actor,root,1,root) returning * into fam;
  insert into public.pro_company_file_family_members(owner_id,file_id,root_id) values(p_actor,root,root);
  insert into public.pro_company_file_versions(owner_id,root_id,version,file_id,kind,created_at) values(p_actor,root,1,root,'original',cur.created_at);
 end if;
 select coalesce(max(version),0)+1 into next_version from public.pro_company_file_versions where owner_id=p_actor and root_id=root;
 if next_version>100 then raise exception 'Version limit' using errcode='54000';end if;
 if act='add_version' then
  insert into public.pro_company_file_family_members(owner_id,file_id,root_id) values(p_actor,nid,root);
  insert into public.pro_company_file_versions(owner_id,root_id,version,file_id,kind,note) values(p_actor,root,next_version,nid,'upload',v_note);
 else
  select * into target from public.pro_company_file_versions where owner_id=p_actor and root_id=root and version=v_version;
  if not found then raise exception 'Unknown version' using errcode='22023';end if;
  if target.file_id=cur.id then raise exception 'That version is already current' using errcode='22023';end if;
  select * into nf from public.pro_company_files where owner_id=p_actor and id=target.file_id for update;
  if not found or not nf.ready then raise exception 'Version unavailable' using errcode='22023';end if;
  insert into public.pro_company_file_versions(owner_id,root_id,version,file_id,kind,restored_from,note) values(p_actor,root,next_version,target.file_id,'restore',v_version,v_note);
 end if;
 -- The file that becomes current keeps the place, favourite and active state of the family.
 if nf.folder_id is distinct from cur.folder_id or nf.favorite<>cur.favorite or nf.archived then
  update public.pro_company_files set folder_id=cur.folder_id,favorite=cur.favorite,archived=false,revision=revision+1 where owner_id=p_actor and id=nf.id;
 end if;
 update public.pro_company_file_families set current_version=next_version,current_file_id=nf.id,revision=revision+1,updated_at=now() where owner_id=p_actor and root_id=root returning * into fam;
 result:=jsonb_build_object('action',act,'family',public.pro_cfv_state(p_actor,root),
  'file',(select public.pro_company_file_json(f) from public.pro_company_files f where f.owner_id=p_actor and f.id=nf.id));
 insert into public.pro_company_file_version_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Moving the current file moves every member of its family (each member gets its next revision).
create or replace function public.pro_cfv_follow_folder() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.folder_id is distinct from old.folder_id and exists(select 1 from public.pro_company_file_families f where f.owner_id=new.owner_id and f.current_file_id=new.id) then
  update public.pro_company_files c set folder_id=new.folder_id,revision=c.revision+1
   where c.owner_id=new.owner_id and c.id<>new.id and c.folder_id is distinct from new.folder_id
    and c.id in(select m.file_id from public.pro_company_file_family_members m where m.owner_id=new.owner_id and m.root_id=(select f.root_id from public.pro_company_file_families f where f.owner_id=new.owner_id and f.current_file_id=new.id));
 end if;
 return null;
end $$;
drop trigger if exists pro_cfv_follow_folder on public.pro_company_files;
create trigger pro_cfv_follow_folder after update of folder_id on public.pro_company_files for each row execute function public.pro_cfv_follow_folder();
create or replace function public.pro_cfv_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin raise exception 'Company file versions are immutable' using errcode='23514';end $$;
drop trigger if exists pro_cfv_versions_immutable on public.pro_company_file_versions;
create trigger pro_cfv_versions_immutable before update on public.pro_company_file_versions for each row execute function public.pro_cfv_immutable();
drop trigger if exists pro_cfv_members_immutable on public.pro_company_file_family_members;
create trigger pro_cfv_members_immutable before update on public.pro_company_file_family_members for each row execute function public.pro_cfv_immutable();
drop trigger if exists pro_cfv_actions_immutable on public.pro_company_file_version_actions;
create trigger pro_cfv_actions_immutable before update on public.pro_company_file_version_actions for each row execute function public.pro_cfv_immutable();
create or replace function public.pro_cfv_family_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.owner_id<>old.owner_id or new.root_id<>old.root_id or new.created_at<>old.created_at or new.revision<>old.revision+1 or new.current_version<=old.current_version then raise exception 'Families only move forward' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_cfv_family_guard on public.pro_company_file_families;
create trigger pro_cfv_family_guard before update on public.pro_company_file_families for each row execute function public.pro_cfv_family_guard();

-- Library listing: same as company-files-local.sql plus pro_cfv_hidden (non-current versions are not listed).
create or replace function public.pro_company_files_read(p_actor uuid,p_scope text default 'folder',p_folder uuid default null,p_status text default 'active',p_query text default '',p_type text default 'all',p_starred boolean default false,p_after text default null,p_file uuid default null) returns jsonb language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare f pro_company_files;items jsonb;ancestors jsonb:='[]'::jsonb;cursor_kind text;cursor_id uuid;next_cursor text;want boolean;needle text;
begin
 if not coalesce(pro_appointment_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_file is not null then select * into f from pro_company_files where owner_id=p_actor and id=p_file and ready;if not found then return null;end if;return jsonb_build_object('file',pro_company_file_json(f),'ancestors',pro_company_ancestors(p_actor,f.folder_id));end if;
 if p_scope is null or p_scope not in('folder','all') or p_scope='all' and p_folder is not null or p_status is null or p_status not in('active','archived') or p_query is null or length(p_query)>100 or p_type is null or p_type not in('all','image','pdf') or p_starred is null then raise exception 'Invalid library query' using errcode='22023';end if;
 if p_scope='folder' then ancestors:=pro_company_ancestors(p_actor,p_folder);end if;want:=p_status='archived';needle:=lower(btrim(p_query));
 if p_after is not null then if not p_after~'^(folder|file):[a-f0-9-]{36}$' then raise exception 'Invalid cursor' using errcode='22023';end if;cursor_kind:=split_part(p_after,':',1);cursor_id:=split_part(p_after,':',2)::uuid;end if;
 -- Both branches have a single current-owner predicate before keyset filtering.
 with candidates as(
  select 'folder'::text kind,d.id,pro_company_folder_json(d) data from pro_company_folders d where d.owner_id=p_actor and d.archived=want and(p_scope='all' or d.parent_id is not distinct from p_folder) and p_type='all' and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)
  union all select 'file',d.id,pro_company_file_json(d) from pro_company_files d where d.owner_id=p_actor and d.ready and d.archived=want and not public.pro_cfv_hidden(p_actor,d.id) and(p_scope='all' or d.folder_id is not distinct from p_folder) and(p_type='all' or p_type='image' and d.mime_type='image/jpeg' or p_type='pdf' and d.mime_type='application/pdf') and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)
 ),eligible as(select *,case kind when 'folder' then 0 else 1 end sort from candidates),paged as(select * from eligible where p_after is null or(sort,id)>(case cursor_kind when 'folder' then 0 else 1 end,cursor_id) order by sort,id limit 21)
 select coalesce(jsonb_agg(jsonb_build_object('kind',kind,kind,data) order by sort,id),'[]'::jsonb) into items from paged;
 if p_after is not null then
  if cursor_kind='folder' then
   if not exists(select 1 from pro_company_folders d where d.owner_id=p_actor and d.id=cursor_id and d.archived=want and(p_scope='all' or d.parent_id is not distinct from p_folder) and p_type='all' and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)) then raise exception 'Cursor changed' using errcode='40001';end if;
  elsif not exists(select 1 from pro_company_files d where d.owner_id=p_actor and d.id=cursor_id and d.ready and d.archived=want and not public.pro_cfv_hidden(p_actor,d.id) and(p_scope='all' or d.folder_id is not distinct from p_folder) and(p_type='all' or p_type='image' and d.mime_type='image/jpeg' or p_type='pdf' and d.mime_type='application/pdf') and(not p_starred or d.favorite) and(needle='' or position(needle in lower(d.name))>0)) then raise exception 'Cursor changed' using errcode='40001';end if;
 end if;
 if jsonb_array_length(items)>20 then next_cursor:=items->19->>'kind';next_cursor:=next_cursor||':'||(items->19->next_cursor->>'id');items:=items-20;end if;
 return jsonb_build_object('items',items,'nextCursor',next_cursor,'ancestors',ancestors);
end $$;

do $$declare t text;f record;begin
 foreach t in array array['pro_company_file_families','pro_company_file_family_members','pro_company_file_versions','pro_company_file_version_actions'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and (p.proname like 'pro\_cfv\_%' or p.proname in('pro_company_file_versions_read','pro_company_file_versions_index','pro_company_file_versions_mutate','pro_company_files_read')) loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname not in('pro_cfv_immutable','pro_cfv_family_guard','pro_cfv_follow_folder') then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;

-- ===== work-client-invitations-local.sql =====
-- LOCAL PRO ONLY. Round 1 after the manual walkthrough (2026-11-12): link a customer ACCOUNT to an
-- existing job ("Invitar al cliente al proyecto"), and let a customer who accepted an estimate shared
-- by code join the job that results from it.
--
-- Model: every customer reader of the suite (customer view, contracts, files, file versions, idea
-- boards, updates, daily logs, selections, allowances, schedule, punch list) already authorizes the
-- customer through ONE confirmed pro_appointment_requests row of the job. A link therefore inserts
-- that same row with origin='project_invite' (not an appointment: no time, no reminders, no notice,
-- excluded from lead lists and from the provider request list; the agenda sync ignores it).
--
-- Invitation: random 32-byte token generated by the server route, shown once to the owner, only its
-- SHA-256 is stored (domain-prefixed by the route). Expires (1..30 days, default 7), revocable, single
-- use; creating a new one revokes the previous open invitation of the job. Nothing is e-mailed.
-- Estimate consent: the verified recipient of an ACCEPTED publication may opt in; the link is made
-- when (or if already) the owner continues that accepted estimate into a job.
begin;
create table if not exists public.pro_work_client_invitations(
 id uuid primary key,
 owner_id uuid not null references public.profiles(id) on delete cascade,
 work_id text not null,
 token_hash text not null unique check(token_hash~'^[a-f0-9]{64}$'),
 created_at timestamptz not null default clock_timestamp(),
 expires_at timestamptz not null,
 revoked_at timestamptz,
 accepted_by uuid references public.profiles(id) on delete cascade,
 accepted_at timestamptz,
 request_id uuid,
 check(expires_at>created_at),
 check((accepted_by is null)=(accepted_at is null)),
 check(accepted_at is null or revoked_at is null),
 foreign key(owner_id,work_id) references public.pro_work(user_id,id) on delete cascade
);
create index if not exists pro_work_client_invitations_work on public.pro_work_client_invitations(owner_id,work_id,created_at desc);
create table if not exists public.pro_work_client_invitation_actions(
 actor_id uuid not null references public.profiles(id) on delete cascade,action_id uuid not null,
 input jsonb not null,result jsonb not null,at timestamptz not null default clock_timestamp(),
 primary key(actor_id,action_id),check(not(input?'token'))
);
create table if not exists public.pro_work_client_link_consents(
 publication_id uuid primary key references public.pro_private_estimate_publications(id) on delete cascade,
 owner_id uuid not null references public.profiles(id) on delete cascade,
 client_user_id uuid not null references public.profiles(id) on delete cascade,
 at timestamptz not null default clock_timestamp(),
 request_id uuid
);

create or replace function public.pro_work_client_invitation_state(p_row public.pro_work_client_invitations) returns text
language sql stable security invoker set search_path=public,pg_temp as $$
 select case when p_row.accepted_at is not null then 'accepted' when p_row.revoked_at is not null then 'revoked'
  when p_row.expires_at<=clock_timestamp() then 'expired' else 'active' end $$;
create or replace function public.pro_work_client_invitation_json(p_row public.pro_work_client_invitations) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('id',p_row.id,'state',public.pro_work_client_invitation_state(p_row),'createdAt',p_row.created_at,
  'expiresAt',p_row.expires_at,'revokedAt',p_row.revoked_at,'acceptedAt',p_row.accepted_at) $$;
-- Linked customer account of the job (any origin), the same rule as every shared reader.
create or replace function public.pro_work_client_link_json(p_owner uuid,p_work text) returns jsonb
language sql stable security invoker set search_path=public,pg_temp as $$
 select jsonb_build_object('requestId',r.id,'name',r.client_name,'origin',r.origin,'linkedAt',r.updated_at)
 from public.pro_appointment_requests r join public.profiles c on c.id=r.client_user_id
 where r.owner_id=p_owner and r.work_id=p_work and r.status in('confirmed','completed') and not coalesce(c.is_disabled,false)
 order by r.updated_at desc,r.id desc limit 1 $$;

-- Internal: link p_client to the owner's job. Caller holds the owner mutex
-- (hashtextextended(owner,0), the same lock as the appointment workflow).
create or replace function public.pro_work_client_link_apply(p_owner uuid,p_work text,p_client uuid) returns uuid
language plpgsql security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;prof public.professionals;r public.pro_appointment_requests;who public.profiles;rid uuid;prior text;label text;
begin
 if p_client is null or p_owner is null or p_client=p_owner then raise exception 'Own job' using errcode='42501',hint='pro_invite_own';end if;
 select * into who from public.profiles where id=p_client and not coalesce(is_disabled,false);
 if not found then raise exception 'Account unavailable' using errcode='42501';end if;
 select * into w from public.pro_work where user_id=p_owner and id=p_work;
 if not found or coalesce(w.cancelled,false) then raise exception 'Job unavailable' using errcode='40001',hint='pro_invite_work';end if;
 select * into prof from public.professionals where profile_id=p_owner and not coalesce(is_banned,false) order by id limit 1;
 if not found then raise exception 'Professional profile required' using errcode='22023',hint='pro_invite_profile';end if;
 label:=coalesce(nullif(left(btrim(w.service),160),''),'Proyecto');
 select * into r from public.pro_appointment_requests where owner_id=p_owner and work_id=p_work for update;
 prior:=current_setting('contratacr.project_link',true);
 if found then
  if r.client_user_id=p_client and r.status in('confirmed','completed') then return r.id;end if;
  if r.origin<>'project_invite' or r.status in('confirmed','completed') then raise exception 'Another customer is linked' using errcode='40001',hint='pro_invite_linked';end if;
  -- A previously unlinked invitation row is reused (one row per job): new account, confirmed again.
  perform set_config('contratacr.project_link',r.id::text,true);
  update public.pro_appointment_requests set client_user_id=p_client,client_name=left(coalesce(nullif(btrim(who.full_name),''),nullif(btrim(w.client),''),'Cliente'),160),
   service=label,status='confirmed',revision=revision+1,updated_at=now() where id=r.id;
  perform set_config('contratacr.project_link',coalesce(prior,''),true);rid:=r.id;
 else
  rid:=gen_random_uuid();
  insert into public.pro_appointment_requests(id,professional_id,owner_id,client_user_id,client_name,professional_name,professional_slug,service,duration_minutes,location_kind,location_text,note,status,revision,work_id,origin)
  values(rid,prof.id,p_owner,p_client,left(coalesce(nullif(btrim(who.full_name),''),nullif(btrim(w.client),''),'Cliente'),160),left(coalesce(nullif(btrim(prof.business_name),''),'Profesional'),160),prof.slug,
   label,60,'agree','','','confirmed',0,p_work,'project_invite');
 end if;
 -- 'project_link' is not an appointment notice action: no notification, no reminder.
 insert into public.pro_appointment_events(request_id,actor_id,side,action,note,status) values(rid,p_client,'client','project_link','','confirmed');
 return rid;
end $$;

-- Rows created by invitation change only through this module (flag set by the functions above).
create or replace function public.pro_work_client_link_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.origin is distinct from old.origin then raise exception 'Request origin is immutable' using errcode='23514';end if;
 if old.origin='project_invite' and coalesce(current_setting('contratacr.project_link',true),'')<>old.id::text then raise exception 'Use the project invitation workflow' using errcode='23514',hint='pro_invite_workflow';end if;
 return new;
end $$;
drop trigger if exists pro_work_client_link_guard on public.pro_appointment_requests;
create trigger pro_work_client_link_guard before update on public.pro_appointment_requests for each row execute function public.pro_work_client_link_guard();

create or replace function public.pro_work_client_invitations_read(p_actor uuid,p_work text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare w public.pro_work;items jsonb;linked jsonb;has_profile boolean;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_work is null or length(p_work) not between 1 and 160 then raise exception 'Invalid invitation query' using errcode='22023';end if;
 select * into w from public.pro_work where user_id=p_actor and id=p_work;if not found then return null;end if;
 linked:=public.pro_work_client_link_json(p_actor,p_work);
 select exists(select 1 from public.professionals where profile_id=p_actor and not coalesce(is_banned,false)) into has_profile;
 select coalesce(jsonb_agg(public.pro_work_client_invitation_json(i) order by i.created_at desc),'[]'::jsonb) into items
  from (select * from public.pro_work_client_invitations where owner_id=p_actor and work_id=p_work order by created_at desc limit 10) i;
 return jsonb_build_object('workId',p_work,'service',w.service,'client',w.client,'cancelled',coalesce(w.cancelled,false),'linked',linked,'invitations',items,
  'canInvite',linked is null and not coalesce(w.cancelled,false) and has_profile,'profileMissing',not has_profile);
end $$;

-- Customer record ("ficha del cliente"): that customer's jobs with their linked account, newest first.
create or replace function public.pro_work_client_invite_jobs(p_actor uuid,p_client text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if p_client is null or length(p_client) not between 1 and 160 then raise exception 'Invalid customer query' using errcode='22023';end if;
 if not exists(select 1 from public.pro_clients where user_id=p_actor and id=p_client) then return null;end if;
 select coalesce(jsonb_agg(x.content order by x.position desc),'[]'::jsonb) into items from(
  select w.position,jsonb_build_object('workId',w.id,'service',w.service,'stage',w.stage,'cancelled',coalesce(w.cancelled,false),'linked',public.pro_work_client_link_json(p_actor,w.id)) content
  from public.pro_work w where w.user_id=p_actor and w."clientId"=p_client order by w.position desc limit 20) x;
 return jsonb_build_object('clientId',p_client,'items',items);
end $$;
create or replace function public.pro_work_client_invitations_mutate(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare act text;aid uuid;wid text;iid uuid;keys text[];prior public.pro_work_client_invitation_actions;w public.pro_work;i public.pro_work_client_invitations;r public.pro_appointment_requests;days integer;result jsonb;flag text;
begin
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or jsonb_typeof(p_input->'action') is distinct from 'string' then raise exception 'Invalid invitation' using errcode='22023';end if;
 act:=p_input->>'action';select array_agg(key order by key) into keys from jsonb_object_keys(p_input) key;
 if keys is distinct from (case act when 'create' then array['action','actionId','expiresInDays','invitationId','tokenHash','workId'] when 'revoke' then array['action','actionId','invitationId','workId'] when 'unlink' then array['action','actionId','requestId','workId'] end)
  or jsonb_typeof(p_input->'workId') is distinct from 'string' or length(p_input->>'workId') not between 1 and 160 then raise exception 'Invalid invitation fields' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;wid:=p_input->>'workId';
 if act='create' and (not coalesce(p_input->>'tokenHash'~'^[a-f0-9]{64}$',false) or jsonb_typeof(p_input->'expiresInDays') is distinct from 'number' or not coalesce(p_input->>'expiresInDays'~'^[0-9]{1,2}$',false)) then raise exception 'Invalid invitation values' using errcode='22023';end if;
 if act='create' then days:=(p_input->>'expiresInDays')::integer;if days not between 1 and 30 then raise exception 'Invalid expiry' using errcode='22023';end if;end if;
 if act in('create','revoke') then iid:=(p_input->>'invitationId')::uuid;end if;
 perform pg_advisory_xact_lock(hashtextextended(p_actor::text,0));
 if not coalesce(public.pro_private_work_tools_enabled(p_actor),false) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into prior from public.pro_work_client_invitation_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into w from public.pro_work where user_id=p_actor and id=wid;if not found then raise exception 'Forbidden' using errcode='42501';end if;
 if act='create' then
  if coalesce(w.cancelled,false) then raise exception 'Job cancelled' using errcode='40001',hint='pro_invite_work';end if;
  if public.pro_work_client_link_json(p_actor,wid) is not null then raise exception 'Customer already linked' using errcode='40001',hint='pro_invite_linked';end if;
  if not exists(select 1 from public.professionals where profile_id=p_actor and not coalesce(is_banned,false)) then raise exception 'Professional profile required' using errcode='22023',hint='pro_invite_profile';end if;
  if exists(select 1 from public.pro_work_client_invitations where id=iid) or exists(select 1 from public.pro_work_client_invitations where token_hash=p_input->>'tokenHash') then raise exception 'Invitation identity reused' using errcode='40001';end if;
  if (select count(*) from public.pro_work_client_invitations where owner_id=p_actor and created_at>clock_timestamp()-interval '1 day')>=50 then raise exception 'Invitation limit' using errcode='54000';end if;
  update public.pro_work_client_invitations set revoked_at=clock_timestamp() where owner_id=p_actor and work_id=wid and accepted_at is null and revoked_at is null and expires_at>clock_timestamp();
  insert into public.pro_work_client_invitations(id,owner_id,work_id,token_hash,expires_at) values(iid,p_actor,wid,p_input->>'tokenHash',clock_timestamp()+make_interval(days=>days)) returning * into i;
  result:=jsonb_build_object('action','create','invitation',public.pro_work_client_invitation_json(i));
 elsif act='revoke' then
  select * into i from public.pro_work_client_invitations where id=iid and owner_id=p_actor and work_id=wid for update;
  if not found then raise exception 'Invitation unavailable' using errcode='42501';end if;
  if i.accepted_at is not null then raise exception 'Invitation already used' using errcode='40001',hint='pro_invite_used';end if;
  if i.revoked_at is null then update public.pro_work_client_invitations set revoked_at=clock_timestamp() where id=i.id returning * into i;end if;
  result:=jsonb_build_object('action','revoke','invitation',public.pro_work_client_invitation_json(i));
 else
  select * into r from public.pro_appointment_requests where id=(p_input->>'requestId')::uuid and owner_id=p_actor and work_id=wid for update;
  if not found then raise exception 'Link unavailable' using errcode='42501';end if;
  -- Accounts that booked through the public calendar keep the appointment workflow.
  if r.origin<>'project_invite' then raise exception 'Booking link' using errcode='40001',hint='pro_invite_booking';end if;
  if r.status not in('confirmed','completed') then raise exception 'Already unlinked' using errcode='40001';end if;
  flag:=current_setting('contratacr.project_link',true);perform set_config('contratacr.project_link',r.id::text,true);
  update public.pro_appointment_requests set status='cancelled',revision=revision+1,updated_at=now() where id=r.id;
  perform set_config('contratacr.project_link',coalesce(flag,''),true);
  insert into public.pro_appointment_events(request_id,actor_id,side,action,note,status) values(r.id,p_actor,'provider','project_unlink','','cancelled');
  result:=jsonb_build_object('action','unlink','requestId',r.id);
 end if;
 insert into public.pro_work_client_invitation_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Customer side. Reveals only the professional's public name, the job title and the expiry.
create or replace function public.pro_work_client_invitation_preview(p_actor uuid,p_token_hash text) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare i public.pro_work_client_invitations;w public.pro_work;prof public.professionals;st text;linked jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if not coalesce(p_token_hash~'^[a-f0-9]{64}$',false) then raise exception 'Invalid code' using errcode='22023';end if;
 select * into i from public.pro_work_client_invitations where token_hash=p_token_hash;
 if not found then return jsonb_build_object('state','unknown');end if;
 if i.accepted_by=p_actor then return jsonb_build_object('state','linked','requestId',i.request_id);end if;
 st:=public.pro_work_client_invitation_state(i);
 if st='accepted' then return jsonb_build_object('state','used');end if;
 if st<>'active' then return jsonb_build_object('state',st);end if;
 if i.owner_id=p_actor then return jsonb_build_object('state','own');end if;
 select * into w from public.pro_work where user_id=i.owner_id and id=i.work_id;
 linked:=public.pro_work_client_link_json(i.owner_id,i.work_id);
 if not found or coalesce(w.cancelled,false) or linked is not null or not coalesce(public.pro_appointment_enabled(i.owner_id),false) then return jsonb_build_object('state','unavailable');end if;
 select * into prof from public.professionals where profile_id=i.owner_id and not coalesce(is_banned,false) order by id limit 1;
 return jsonb_build_object('state','valid','professionalName',left(coalesce(nullif(btrim(prof.business_name),''),'Profesional'),160),
  'service',coalesce(nullif(left(btrim(w.service),160),''),'Proyecto'),'expiresAt',i.expires_at);
end $$;

create or replace function public.pro_work_client_invitation_accept(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;h text;i public.pro_work_client_invitations;prior public.pro_work_client_invitation_actions;rid uuid;st text;result jsonb;r public.pro_appointment_requests;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(p_input) key) is distinct from array['action','actionId','tokenHash']
  or p_input->>'action' is distinct from 'accept' or not coalesce(p_input->>'tokenHash'~'^[a-f0-9]{64}$',false) then raise exception 'Invalid acceptance' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;h:=p_input->>'tokenHash';
 select * into i from public.pro_work_client_invitations where token_hash=h;
 if not found then raise exception 'Code unavailable' using errcode='P0002',hint='pro_invite_unknown';end if;
 -- Lock order: owner mutex -> invitation -> request (same as the owner mutations).
 perform pg_advisory_xact_lock(hashtextextended(i.owner_id::text,0));
 select * into prior from public.pro_work_client_invitation_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into i from public.pro_work_client_invitations where id=i.id for update;
 if i.accepted_by=p_actor then
  result:=jsonb_build_object('action','accept','requestId',i.request_id,'alreadyLinked',true);
 else
  st:=public.pro_work_client_invitation_state(i);
  if st='accepted' then raise exception 'Code used' using errcode='P0002',hint='pro_invite_used';end if;
  if st='revoked' then raise exception 'Code revoked' using errcode='P0002',hint='pro_invite_revoked';end if;
  if st='expired' then raise exception 'Code expired' using errcode='P0002',hint='pro_invite_expired';end if;
  if i.owner_id=p_actor then raise exception 'Own job' using errcode='42501',hint='pro_invite_own';end if;
  if not coalesce(public.pro_appointment_enabled(i.owner_id),false) then raise exception 'Professional unavailable' using errcode='40001',hint='pro_invite_work';end if;
  rid:=public.pro_work_client_link_apply(i.owner_id,i.work_id,p_actor);
  update public.pro_work_client_invitations set accepted_by=p_actor,accepted_at=clock_timestamp(),request_id=rid where id=i.id;
  select * into r from public.pro_appointment_requests where id=rid;
  result:=jsonb_build_object('action','accept','requestId',rid,'professionalName',r.professional_name,'service',r.service,'alreadyLinked',false);
 end if;
 insert into public.pro_work_client_invitation_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;

-- Estimate shared by code: consent of the verified recipient of an ACCEPTED version.
create or replace function public.pro_work_client_link_consent_read(p_actor uuid,p_publication uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare v public.pro_private_estimate_publications;s public.pro_private_estimate_publication_states;c public.pro_work_client_link_consents;a public.pro_private_estimate_work_agreements;r public.pro_appointment_requests;prof text;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select * into v from public.pro_private_estimate_publications where id=p_publication;
 select * into s from public.pro_private_estimate_publication_states where publication_id=p_publication;
 if v.id is null or s.recipient_id is distinct from p_actor then return null;end if;
 select left(coalesce(nullif(btrim(p.business_name),''),'Profesional'),160) into prof from public.professionals p where p.profile_id=v.owner_id order by p.id limit 1;
 select * into c from public.pro_work_client_link_consents where publication_id=p_publication and client_user_id=p_actor;
 select * into a from public.pro_private_estimate_work_agreements where publication_id=p_publication;
 if a.work_id is not null then select * into r from public.pro_appointment_requests where owner_id=v.owner_id and work_id=a.work_id and client_user_id=p_actor and status in('confirmed','completed');end if;
 -- Round 7A: a customer already linked to the job of this quote (its source job, or the job it was
 -- shared to as «linked customer») is not asked to join again.
 if r.id is null then
  select ar.* into r from public.pro_appointment_requests ar join public.pro_private_estimates d on d.owner_id=v.owner_id and d.id=v.estimate_id
   left join public.pro_private_estimate_publication_recipients b on b.owner_id=v.owner_id and b.estimate_id=v.estimate_id
   where ar.owner_id=v.owner_id and ar.client_user_id=p_actor and ar.status in('confirmed','completed') and ar.work_id is not null
    and(d.source->>'kind'='work' and ar.work_id=d.source->>'id' or b.proof->>'kind'='linked' and ar.id::text=b.proof->>'requestId')
   order by ar.updated_at desc,ar.id desc limit 1;
 end if;
 return jsonb_build_object('publicationId',p_publication,'eligible',s.status='accepted','consented',c.publication_id is not null,'consentedAt',c.at,
  'jobReady',a.work_id is not null or r.id is not null,'requestId',r.id,'professionalName',coalesce(prof,'Profesional'));
end $$;
create or replace function public.pro_work_client_link_consent(p_actor uuid,p_input jsonb) returns jsonb
language plpgsql security invoker set search_path=public,pg_temp as $$
declare aid uuid;pid uuid;v public.pro_private_estimate_publications;s public.pro_private_estimate_publication_states;a public.pro_private_estimate_work_agreements;prior public.pro_work_client_invitation_actions;rid uuid;status text;result jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 if jsonb_typeof(p_input) is distinct from 'object' or (select array_agg(key order by key) from jsonb_object_keys(p_input) key) is distinct from array['action','actionId','publicationId']
  or p_input->>'action' is distinct from 'consent' then raise exception 'Invalid consent' using errcode='22023';end if;
 aid:=(p_input->>'actionId')::uuid;pid:=(p_input->>'publicationId')::uuid;
 select * into v from public.pro_private_estimate_publications where id=pid;if not found then raise exception 'Publication unavailable' using errcode='42501';end if;
 perform pg_advisory_xact_lock(hashtextextended(v.owner_id::text,0));
 select * into prior from public.pro_work_client_invitation_actions where actor_id=p_actor and action_id=aid;
 if found then if prior.input is distinct from p_input then raise exception 'Action identity reused' using errcode='22023';end if;return prior.result||jsonb_build_object('replayed',true);end if;
 select * into s from public.pro_private_estimate_publication_states where publication_id=pid for share;
 -- Only the verified recipient, and only once that version was accepted.
 if s.recipient_id is distinct from p_actor then raise exception 'Forbidden' using errcode='42501';end if;
 if s.status<>'accepted' then raise exception 'Accept the estimate first' using errcode='40001',hint='pro_consent_not_accepted';end if;
 insert into public.pro_work_client_link_consents(publication_id,owner_id,client_user_id) values(pid,v.owner_id,p_actor) on conflict(publication_id) do nothing;
 select * into a from public.pro_private_estimate_work_agreements where publication_id=pid;
 status:='pending';
 if found then
  begin rid:=public.pro_work_client_link_apply(v.owner_id,a.work_id,p_actor);status:='linked';
  exception when others then status:='unavailable';end;
  if rid is not null then update public.pro_work_client_link_consents set request_id=rid where publication_id=pid;end if;
 end if;
 result:=jsonb_build_object('action','consent','status',status,'requestId',rid);
 insert into public.pro_work_client_invitation_actions(actor_id,action_id,input,result) values(p_actor,aid,p_input,result);
 return result;
end $$;
-- When the owner continues an accepted estimate into a job, a recorded consent links the account.
-- A failure (e.g. another account already linked) never blocks the owner's continuation.
create or replace function public.pro_work_client_link_on_agreement() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
declare c public.pro_work_client_link_consents;rid uuid;
begin
 select * into c from public.pro_work_client_link_consents where publication_id=new.publication_id and client_user_id=new.accepted_actor_id;
 if found then
  begin perform pg_advisory_xact_lock(hashtextextended(new.owner_id::text,0));rid:=public.pro_work_client_link_apply(new.owner_id,new.work_id,c.client_user_id);
  exception when others then rid:=null;end;
  if rid is not null then update public.pro_work_client_link_consents set request_id=rid where publication_id=new.publication_id;end if;
 end if;
 return new;
end $$;
drop trigger if exists pro_work_client_link_on_agreement on public.pro_private_estimate_work_agreements;
create trigger pro_work_client_link_on_agreement after insert on public.pro_private_estimate_work_agreements for each row execute function public.pro_work_client_link_on_agreement();

-- Customer panel: jobs the account is linked to (any origin), newest first.
create or replace function public.pro_work_client_links_client(p_actor uuid) returns jsonb
language plpgsql stable security invoker set search_path=public,pg_temp as $$
declare items jsonb;
begin
 if not exists(select 1 from public.profiles where id=p_actor and not coalesce(is_disabled,false)) then raise exception 'Forbidden' using errcode='42501';end if;
 select coalesce(jsonb_agg(x.content order by x.at desc,x.id),'[]'::jsonb) into items from(
  select r.updated_at at,r.id,jsonb_build_object('requestId',r.id,'service',r.service,'professionalName',r.professional_name,'origin',r.origin,'linkedAt',r.updated_at,
   'stage',w.stage,'cancelled',coalesce(w.cancelled,false)) content
  from public.pro_appointment_requests r join public.pro_work w on w.user_id=r.owner_id and w.id=r.work_id
  where r.client_user_id=p_actor and r.status in('confirmed','completed') order by r.updated_at desc limit 50) x;
 return jsonb_build_object('items',items);
end $$;

create or replace function public.pro_work_client_invitation_immutable() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if tg_op='DELETE' and pg_trigger_depth()>1 then return old;end if;
 raise exception 'Invitation receipts are immutable' using errcode='23514';
end $$;
drop trigger if exists pro_work_client_invitation_action_immutable on public.pro_work_client_invitation_actions;
create trigger pro_work_client_invitation_action_immutable before update on public.pro_work_client_invitation_actions for each row execute function public.pro_work_client_invitation_immutable();
-- Token hashes never change once stored.
create or replace function public.pro_work_client_invitation_guard() returns trigger
language plpgsql security invoker set search_path=public,pg_temp as $$
begin
 if new.token_hash is distinct from old.token_hash or new.owner_id is distinct from old.owner_id or new.work_id is distinct from old.work_id or new.expires_at is distinct from old.expires_at or new.created_at is distinct from old.created_at
  or old.accepted_at is not null and (new.accepted_at is distinct from old.accepted_at or new.accepted_by is distinct from old.accepted_by)
  or old.revoked_at is not null and new.revoked_at is distinct from old.revoked_at then raise exception 'Invitation identity is immutable' using errcode='23514';end if;
 return new;
end $$;
drop trigger if exists pro_work_client_invitation_guard on public.pro_work_client_invitations;
create trigger pro_work_client_invitation_guard before update on public.pro_work_client_invitations for each row execute function public.pro_work_client_invitation_guard();

do $$declare t text;f record;begin
 foreach t in array array['pro_work_client_invitations','pro_work_client_invitation_actions','pro_work_client_link_consents'] loop
  execute format('alter table public.%I enable row level security',t);
  execute format('revoke all on public.%I from public,anon,authenticated',t);
  execute format('grant select,insert,update,delete on public.%I to service_role',t);
 end loop;
 for f in select p.oid::regprocedure signature,p.proname from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='public' and p.proname like 'pro\_work\_client\_%' loop
  execute format('revoke all on function %s from public,anon,authenticated',f.signature);
  if f.proname in('pro_work_client_invitations_read','pro_work_client_invite_jobs','pro_work_client_invitations_mutate','pro_work_client_invitation_preview','pro_work_client_invitation_accept','pro_work_client_link_consent_read','pro_work_client_link_consent','pro_work_client_links_client')
  then execute format('grant execute on function %s to service_role',f.signature);end if;
 end loop;
end $$;
notify pgrst,'reload schema';
commit;
